[CCB with maximum norm difference]\label{thm:ccb_max}
Suppose $(\log d)^{5}\maxdiff = O(1)$, then we have

\begin{equation}\label{eq:ccb_max}
    \sup_{0\le t \le C_0\sqrt{\log d}}\left|\frac{\mathbb{P}(\maxnorm{U} > t)}{\mathbb{P}(\maxnorm{V} > t)}-1\right| = O \left( (\log d)^{5/2}\maxdiff^{1/2} \right),


\end{equation}
for some constant $C_0>0$.

[CCB with elementwise $\ell_{0}$-norm difference]\label{thm:ccb_sparse_unitvar}

Assume the Gaussian random vectors $U$ and $V$ have unit variances, i.e., $\sigma^U_{jj}=\sigma^V_{jj}=1, j \in [d]$ and 

there exists some $\sigma_0<1$ such that $|\sigma^V_{jk} |\le  \sigma_0, |\sigma^U_{jk} | \le \sigma_0$ for any $j\ne k$. 

Suppose there exists a disjoint $\discon$-partition of nodes $\cup_{\ell=1}^{\discon}\cC_\ell = [d]$ such that  $\sigma^U_{jk}=\sigma^V_{jk}=0$ when $j \in \cC_{\ell}$ and  $k \in \cC_{\ell'}$ for some $\ell \neq \ell'$. We have
\begin{equation}\label{eq:ccb_sparse_unitvar}
  \sup_{0\le t \le C_0 \sqrt{\log d}} \left|\frac{\mathbb{P}(\maxnorm{U} > t)}{\mathbb{P}(\maxnorm{V} > t)}-1\right| = O\left(\frac{ \zerodiff \log d  }{\discon}\right),
\end{equation}
for some constant $C_0 > 0$.

[FDP/FDR control]\label{thm:fdr_linear}
Under Assumption \ref{asp:dlasso} and the scaling condition  
    $

\frac{d_2\log d_2 + d_0}{d_0 d_2 \rho} +   \frac{s \log^2 d_2 }{n^{1/2}} + 
     \frac{\log^2 d_2}{(n \rho)^{1/5}} 


     = o(1)$, 



if we implement the StarTrek procedure in Algorithm \ref{algo:startrek} with $\bTheta$ estimated by \eqref{eq:dlasso} and the quantiles approximated by \eqref{eq:dlasso_chat},  as $(n,d_1, d_2)\rightarrow \infty$, we have
\begin{equation}\label{eq:fdp_linear}

     \mathrm{FDP} \le q\frac{d_0}{d_1} + \smallop \quad \text{and}
    \quad   \lim_{(n,d_1, d_2)\rightarrow \infty}\mathrm{FDR} \le q\frac{d_{0}}{d_1}.
\end{equation}

[FDP/FDR control]\label{thm:fdr_hub}
Under Assumption \ref{asp:tradeoff_fdp},


the StarTrek procedure in Algorithm \ref{algo:startrek} with \eqref{eq:ggm_tdTheta} as input and the quantiles approximated by \eqref{eq:ggm_chat} satisfies:




as $(n,d)\rightarrow \infty$,
\begin{equation}\label{eq:fdp_hub}


    \mathrm{FDP} \le q\frac{d_0}{d} + \smallop \quad \text{and}
    \quad \lim_{(n,d)\rightarrow \infty}\mathrm{FDR} \le q\frac{d_{0}}{d}.
\end{equation}

\label{thm:fdr_gen}
Under Assumptions \ref{asmp:zeta12} and \ref{asp:tradeoff_fdp_gen}, the StarTrek procedure in Algorithm \ref{algo:startrek} with the generic estimator $\tTheta$ and the approximated quantiles \eqref{eq:ggm_gen} satisfies:
as $(n,d)\rightarrow \infty$,
\begin{equation}\nonumber

    \mathrm{FDP} \le q{d_0}/{d} + \smallop \quad \text{and}
    \quad \lim_{(n,d)\rightarrow \infty}\mathrm{FDP} \le q{d_{0}}/{d}.
\end{equation}
